// AC-WT-001, AC-WT-003, AC-WT-004, AC-WT-005, AC-WT-006.
using System;
using System.Collections.Generic;
using AcadeGameMaker.Core;
using AcadeGameMaker.Transfer;
using NUnit.Framework;

namespace AcadeGameMaker.Tests.EditMode.Transfer
{
    internal sealed class TransferM1Tests
    {
        [Test] public void DistanceKeysPreserveFivePointNineNineNineSixAndSixPointZeroZeroOne() { Assert.That(TransferSelector.PlayerDistanceKey(0,0,5999,0),Is.EqualTo(35988));Assert.That(TransferSelector.PlayerDistanceKey(0,0,6000,0),Is.EqualTo(36000));Assert.That(TransferSelector.PlayerDistanceKey(0,0,6001,0),Is.EqualTo(36012)); }
        [Test] public void MouseTwentyThreeTwentyFourTwentyFiveAndGamepadSeventeenPointNineEighteenEighteenPointOneAreExact() { var mouse=Sample(0,AimSource.MousePointer);Assert.That(TransferSelector.Select(new SimulationTick(0),mouse,new[]{Obs("a",0,529,999)},string.Empty).SelectedTargetId,Is.EqualTo("a"));Assert.That(TransferSelector.Select(new SimulationTick(0),mouse,new[]{Obs("a",0,576,999)},string.Empty).SelectedTargetId,Is.EqualTo("a"));Assert.That(TransferSelector.Select(new SimulationTick(0),mouse,new[]{Obs("a",0,625,999)},string.Empty).SelectedTargetId,Is.Empty);var pad=Sample(0,AimSource.GamepadStick);Assert.That(TransferSelector.Select(new SimulationTick(0),pad,new[]{Obs("a",0,999,179)},string.Empty).SelectedTargetId,Is.EqualTo("a"));Assert.That(TransferSelector.Select(new SimulationTick(0),pad,new[]{Obs("a",0,999,180)},string.Empty).SelectedTargetId,Is.EqualTo("a"));Assert.That(TransferSelector.Select(new SimulationTick(0),pad,new[]{Obs("a",0,999,181)},string.Empty).SelectedTargetId,Is.Empty); }
        [Test] public void MouseTwentyThreeTwentyFourTwentyFiveAndOrdinalOrderingAreStable() { var s=Sample(0,AimSource.MousePointer);var selected=TransferSelector.Select(new SimulationTick(0),s,new[]{Obs("b",0,576,1),Obs("a",0,576,1),Obs("c",0,625,1)},string.Empty);Assert.That(selected.SelectedTargetId,Is.EqualTo("a"));Assert.That(selected.InsideRank,Is.EqualTo(1)); }
        [Test] public void GamepadRetainsTwentyFivePointNineAndTwentySixButNotTwentySixPointOne() { var s=Sample(0,AimSource.GamepadStick);Assert.That(TransferSelector.Select(new SimulationTick(0),s,new[]{Obs("old",0,1,259)},"old").SelectedTargetId,Is.EqualTo("old"));Assert.That(TransferSelector.Select(new SimulationTick(0),s,new[]{Obs("old",0,1,260)},"old").SelectedTargetId,Is.EqualTo("old"));Assert.That(TransferSelector.Select(new SimulationTick(0),s,new[]{Obs("old",0,1,261)},"old").SelectedTargetId,Is.Empty); }
        [Test] public void EligibleThreePointNineFourFourPointOneReplacementBoundariesAreExact() { var s=Sample(0,AimSource.GamepadStick);Assert.That(TransferSelector.Select(new SimulationTick(0),s,new[]{Obs("old",0,1,220),Obs("new",0,1,181)},"old").SelectedTargetId,Is.EqualTo("old"));Assert.That(TransferSelector.Select(new SimulationTick(0),s,new[]{Obs("old",0,1,220),Obs("new",0,1,180)},"old").SelectedTargetId,Is.EqualTo("new"));Assert.That(TransferSelector.Select(new SimulationTick(0),s,new[]{Obs("old",0,1,220),Obs("new",0,1,179)},"old").SelectedTargetId,Is.EqualTo("new")); }
        [Test] public void InvalidFailurePrecedenceAndContractValidationFailFast() { var s=Sample(0,AimSource.MousePointer);var unavailable=Obs("u",0,1,1,false,false);var trigger=Obs("t",0,1,1,true,true);Assert.That(TransferSelector.Select(new SimulationTick(0),s,new[]{trigger,unavailable},string.Empty).FailureReason,Is.EqualTo(TransferFailureReason.TargetUnavailable));Assert.Throws<ArgumentException>(()=>new TransferTargetDescriptor("bad id",TransferTargetKind.Box,0,0,0,0,1,1,"p",true));Assert.Throws<ArgumentException>(()=>TransferSelector.Select(new SimulationTick(0),s,new[]{Obs("a",0,1,1),Obs("a",0,1,1)},string.Empty)); }
        [Test] public void StaleSampleAndRejectedModifierLeaveSessionUnchanged() { var session=Session(out var sink);session.Evaluate(new SimulationTick(0),Sample(0,AimSource.MousePointer),new[]{Obs("box",0,1,1)});var stale=session.Press(new TransferPressed(1,new SimulationTick(0)));Assert.That(stale.FailureReason,Is.EqualTo(TransferFailureReason.StaleAimSample));sink.Accept=false;var rejected=session.Press(new TransferPressed(0,new SimulationTick(0)));Assert.That(rejected.FailureReason,Is.EqualTo(TransferFailureReason.ModifierRejected));Assert.That(rejected.Session.Revision,Is.EqualTo(0)); }
        [Test] public void ActiveRecallBypassesSelectionButRespectsAgeOneTwentyAndTwentyOne() { var session=Session(out _);session.Evaluate(new SimulationTick(0),Sample(0,AimSource.MousePointer),new[]{Obs("box",0,1,1)});var applied=session.Press(new TransferPressed(0,new SimulationTick(0)));Assert.That(applied.StateChanged.Value.PlayerModifierId,Is.EqualTo("Player.Lightweight.v1"));Assert.That(applied.StateChanged.Value.TargetModifierId,Is.EqualTo("Target.Box.Heavy.v1"));Assert.That(applied.StateChanged.Value.Revision,Is.EqualTo(1));Assert.That(applied.Cleared.HasValue,Is.False);Assert.That(session.Press(new TransferPressed(99,new SimulationTick(1))).FailureReason,Is.EqualTo(TransferFailureReason.Cooldown));Assert.That(session.Press(new TransferPressed(99,new SimulationTick(20))).FailureReason,Is.EqualTo(TransferFailureReason.Cooldown));var clear=session.Press(new TransferPressed(99,new SimulationTick(21)));Assert.That(clear.Cleared.Value.Reason,Is.EqualTo(TransferClearReason.ManualRecall));Assert.That(clear.StateChanged.HasValue,Is.False); }
        [Test] public void SinkBindingAvailabilityAndPublicPayloadInvariantsFailFast() { var session=new TransferSession();Assert.Throws<ArgumentException>(()=>session.Register(new TransferTargetDescriptor("box",TransferTargetKind.Box,0,0,0,0,1,1,"base",true),new Sink("other")));var sink=new Sink("box"){Available=false};session.Register(new TransferTargetDescriptor("box",TransferTargetKind.Box,0,0,0,0,1,1,"base",true),sink);session.Evaluate(new SimulationTick(0),Sample(0,AimSource.MousePointer),new[]{Obs("box",0,1,1)});Assert.That(session.Press(new TransferPressed(0,new SimulationTick(0))).FailureReason,Is.EqualTo(TransferFailureReason.TargetUnavailable));Assert.Throws<ArgumentException>(()=>new AimSample(0,AimSource.GamepadStick,1,1,true,1,0,new SimulationTick(0),new SimulationTick(0)));Assert.Throws<ArgumentException>(()=>new TransferSelectionSnapshot(new SimulationTick(0),TransferSelectionSource.None,"x",-1,-1,-1,-1,TransferFailureReason.None)); }
        [Test] public void CameraAimAndSourceSpecificSelectionPayloadInvariantsAreExact() { Assert.DoesNotThrow(()=>new SimulationCameraPoseSnapshot(new SimulationTick(0),0,0,1000,0,2560,1440,0,0,2560,1440,4));Assert.Throws<ArgumentException>(()=>new SimulationCameraPoseSnapshot(new SimulationTick(0),0,0,1000,0,2560,1440,1,0,2560,1440,4));Assert.Throws<ArgumentOutOfRangeException>(()=>new AimSample(0,AimSource.MousePointer,1920,0,true,1,0,new SimulationTick(0),new SimulationTick(1)));Assert.Throws<ArgumentException>(()=>new TransferSelectionSnapshot(new SimulationTick(0),TransferSelectionSource.MousePointer,"box",-1,0,0,-1,TransferFailureReason.None));Assert.Throws<ArgumentException>(()=>new TransferModifierRequest("box",TransferTargetKind.Box,"base","Target.Enemy.Heavy.v1",new SimulationTick(0),1)); }
        [Test] public void OverflowAndDefaultObservationNeverMutateSinkOrSession() { var session=Session(out var sink);Assert.Throws<OverflowException>(()=>TransferSelector.PlayerDistanceKey(int.MinValue,int.MinValue,int.MaxValue,int.MaxValue));Assert.Throws<ArgumentException>(()=>session.Evaluate(new SimulationTick(0),Sample(0,AimSource.MousePointer),new[]{default(TransferCandidateObservation)}));Assert.That(session.Snapshot(new SimulationTick(0)).Revision,Is.EqualTo(0));session.Evaluate(new SimulationTick(int.MaxValue),Sample(int.MaxValue,AimSource.MousePointer),new[]{Obs("box",int.MaxValue,1,1)});Assert.Throws<OverflowException>(()=>session.Press(new TransferPressed(int.MaxValue,new SimulationTick(int.MaxValue))));Assert.That(sink.ApplyCount,Is.EqualTo(0)); }
        [Test] public void ModifierIdsForAllKindsAndLifecycleResetAreExact() { Assert.DoesNotThrow(()=>new TransferModifierRequest("box",TransferTargetKind.Box,"b","Target.Box.Heavy.v1",new SimulationTick(0),1));Assert.DoesNotThrow(()=>new TransferModifierRequest("enemy",TransferTargetKind.Enemy,"b","Target.Enemy.Heavy.v1",new SimulationTick(0),1));Assert.DoesNotThrow(()=>new TransferModifierRequest("boss",TransferTargetKind.BossPayload,"b","Target.BossPayload.ScriptedHeavy.v1",new SimulationTick(0),1));var s=Session(out var sink);s.Evaluate(new SimulationTick(0),Sample(0,AimSource.MousePointer),new[]{Obs("box",0,1,1)});s.Press(new TransferPressed(0,new SimulationTick(0)));var first=s.Process(new SimulationTick(1),TransferClearReason.RoomLeaving,new TransferTargetRemoved[0],null,new TransferCandidateObservation[0],null);Assert.That(first.RemovalResult.Value.Session.ActiveTargetId,Is.EqualTo(first.Snapshot.ActiveTargetId));Assert.That(first.RemovalResult.Value.Session.TransitionLockEndTick,Is.EqualTo(-1));Assert.That(sink.ClearCount,Is.EqualTo(1));var repeat=s.Process(new SimulationTick(2),TransferClearReason.RoomLeaving,new TransferTargetRemoved[0],null,new TransferCandidateObservation[0],null);Assert.That(repeat.RemovalResult.HasValue,Is.False);Assert.DoesNotThrow(()=>s.Register(new TransferTargetDescriptor("box",TransferTargetKind.Box,0,0,0,0,1,1,"b",true),sink)); }
        [Test] public void MultiRemovalOrderIsDeterministicAndActiveRemovalKeepsPressCooldown() { var first=RemoveTwo(false);var last=RemoveTwo(true);Assert.That(first,Is.EqualTo(last)); }
        [Test] public void InactivePostRecallLockReturnsCooldownBeforeAimValidation() { var s=Session(out _);s.Evaluate(new SimulationTick(0),Sample(0,AimSource.MousePointer),new[]{Obs("box",0,1,1)});s.Press(new TransferPressed(0,new SimulationTick(0)));s.Press(new TransferPressed(null,new SimulationTick(21)));Assert.That(s.Press(new TransferPressed(null,new SimulationTick(22))).FailureReason,Is.EqualTo(TransferFailureReason.Cooldown)); }
        [Test] public void LifecycleRejectsNonLifecycleReasons() { var s=Session(out _);Assert.Throws<ArgumentException>(()=>s.Process(new SimulationTick(0),TransferClearReason.ManualRecall,new TransferTargetRemoved[0],null,new TransferCandidateObservation[0],null)); }
        [Test] public void RemovalAndLifecycleTakePriorityAndClearIsIdempotent() { var session=Session(out var sink);session.Evaluate(new SimulationTick(0),Sample(0,AimSource.MousePointer),new[]{Obs("box",0,1,1)});session.Press(new TransferPressed(0,new SimulationTick(0)));var removed=session.Process(new SimulationTick(21),null,new[]{new TransferTargetRemoved("box",new SimulationTick(21))},null,new TransferCandidateObservation[0],new TransferPressed(0,new SimulationTick(21)));Assert.That(removed.RemovalResult.Value.Cleared.Value.Reason,Is.EqualTo(TransferClearReason.TargetRemoved));Assert.That(sink.ClearCount,Is.EqualTo(1));var life=session.Process(new SimulationTick(22),TransferClearReason.RoomLeaving,new TransferTargetRemoved[0],null,new TransferCandidateObservation[0],new TransferPressed(0,new SimulationTick(22)));Assert.That(life.PressResult.HasValue,Is.False);Assert.That(life.Snapshot.ActiveTargetId,Is.Empty); }
        // AC-WT-003, AC-WT-005. A scripted exposure ending clears an active
        // transfer but deliberately retains its registration for later reuse.
        [Test] public void TemporaryExposureEndClearsOnceWithoutUnregistering() { var session=Session(out var sink);session.Evaluate(new SimulationTick(0),Sample(0,AimSource.MousePointer),new[]{Obs("box",0,1,1)});session.Press(new TransferPressed(0,new SimulationTick(0)));var tick=new SimulationTick(21);var ended=session.Process(tick,null,new[]{new TransferTargetExposureEnded("box",tick),new TransferTargetExposureEnded("box",tick)},new TransferTargetRemoved[0],null,new TransferCandidateObservation[0],null);Assert.That(ended.RemovalResult.Value.Cleared.Value.Reason,Is.EqualTo(TransferClearReason.TargetRemoved));Assert.That(ended.Snapshot.Revision,Is.EqualTo(2));Assert.That(sink.ClearCount,Is.EqualTo(1));var again=session.Process(new SimulationTick(22),null,new[]{new TransferTargetExposureEnded("box",new SimulationTick(22))},new TransferTargetRemoved[0],null,new TransferCandidateObservation[0],null);Assert.That(again.RemovalResult.HasValue,Is.False);Assert.That(again.Snapshot.Revision,Is.EqualTo(2));session.Evaluate(new SimulationTick(22),Sample(22,AimSource.MousePointer),new[]{Obs("box",22,1,1)});var reused=session.Press(new TransferPressed(22,new SimulationTick(22)));Assert.That(reused.Success,Is.True);Assert.That(reused.StateChanged.Value.TargetId,Is.EqualTo("box"));Assert.That(reused.Session.Revision,Is.EqualTo(3));Assert.Throws<ArgumentException>(()=>session.Register(new TransferTargetDescriptor("box",TransferTargetKind.Box,0,0,0,0,1,1,"base",true),sink)); }
        [Test] public void TemporaryEndThenPermanentRemovalAndLifecycleKeepExistingPrecedence() { var session=Session(out var sink);session.Evaluate(new SimulationTick(0),Sample(0,AimSource.MousePointer),new[]{Obs("box",0,1,1)});session.Press(new TransferPressed(0,new SimulationTick(0)));var tick=new SimulationTick(21);var removed=session.Process(tick,null,new[]{new TransferTargetExposureEnded("box",tick)},new[]{new TransferTargetRemoved("box",tick)},null,new TransferCandidateObservation[0],null);Assert.That(removed.RemovalResult.Value.Session.Revision,Is.EqualTo(2));Assert.That(sink.ClearCount,Is.EqualTo(1));Assert.DoesNotThrow(()=>session.Register(new TransferTargetDescriptor("box",TransferTargetKind.Box,0,0,0,0,1,1,"base",true),sink));var lifeTick=new SimulationTick(22);var lifecycle=session.Process(lifeTick,TransferClearReason.RoomLeaving,new[]{new TransferTargetExposureEnded("box",lifeTick)},new TransferTargetRemoved[0],null,new TransferCandidateObservation[0],null);Assert.That(lifecycle.RemovalResult.HasValue,Is.False);Assert.That(lifecycle.Snapshot.ActiveTargetId,Is.Empty); }
        [Test] public void ThreeIdenticalReplaysMatchSnapshots() { var a=Replay();var b=Replay();var c=Replay();Assert.That(a,Is.EqualTo(b));Assert.That(a,Is.EqualTo(c)); }
        private static List<string> Replay(){var s=Session(out _);var r=new List<string>();for(var t=0;t<45;t++){var sample=Sample(t,AimSource.GamepadStick);s.Evaluate(new SimulationTick(t),sample,new[]{Obs("box",t,1,180)});var result=t==0||t==21?s.Press(new TransferPressed(t,new SimulationTick(t))):default(TransferAttemptResult);var q=s.Snapshot(new SimulationTick(t));r.Add(q.Tick.Value+":"+q.HighlightedTargetId+":"+q.ActiveTargetId+":"+q.PlayerState+":"+q.TransitionLockEndTick+":"+q.LastFailureReason+":"+q.Revision+":"+(result.StateChanged.HasValue?result.StateChanged.Value.TargetId+"/"+result.StateChanged.Value.TargetModifierId+"/"+result.StateChanged.Value.Tick.Value+"/"+result.StateChanged.Value.Revision:"")+":"+(result.Cleared.HasValue?result.Cleared.Value.PreviousTargetId+"/"+result.Cleared.Value.Reason+"/"+result.Cleared.Value.Tick.Value+"/"+result.Cleared.Value.Revision:""));}return r;}
        private static string RemoveTwo(bool activeLast){var s=Session(out var box);var other=new Sink("other");s.Register(new TransferTargetDescriptor("other",TransferTargetKind.Enemy,0,0,0,0,1,1,"b",true),other);s.Evaluate(new SimulationTick(0),Sample(0,AimSource.MousePointer),new[]{Obs("box",0,1,1)});s.Press(new TransferPressed(0,new SimulationTick(0)));var removals=activeLast?new[]{new TransferTargetRemoved("other",new SimulationTick(1)),new TransferTargetRemoved("box",new SimulationTick(1))}:new[]{new TransferTargetRemoved("box",new SimulationTick(1)),new TransferTargetRemoved("other",new SimulationTick(1))};var outcome=s.Process(new SimulationTick(1),null,removals,Sample(1,AimSource.MousePointer),new[]{Obs("other",1,1,1)},new TransferPressed(1,new SimulationTick(1)));Assert.That(outcome.RemovalResult.Value.Cleared.Value.Reason,Is.EqualTo(TransferClearReason.TargetRemoved));Assert.That(outcome.PressResult.Value.FailureReason,Is.EqualTo(TransferFailureReason.Cooldown));Assert.That(outcome.Snapshot.TransitionLockEndTick,Is.EqualTo(21));Assert.That(outcome.Snapshot.HighlightedTargetId,Is.Empty);Assert.That(box.ClearCount,Is.EqualTo(1));Assert.DoesNotThrow(()=>s.Register(new TransferTargetDescriptor("box",TransferTargetKind.Box,0,0,0,0,1,1,"b",true),box));Assert.DoesNotThrow(()=>s.Register(new TransferTargetDescriptor("other",TransferTargetKind.Enemy,0,0,0,0,1,1,"b",true),other));return outcome.Snapshot.Tick.Value+":"+outcome.Snapshot.HighlightedTargetId+":"+outcome.Snapshot.ActiveTargetId+":"+outcome.Snapshot.PlayerState+":"+outcome.Snapshot.TransitionLockEndTick+":"+outcome.Snapshot.Revision+":"+outcome.RemovalResult.Value.Cleared.Value.PreviousTargetId+":"+outcome.PressResult.Value.FailureReason;}
        private static TransferSession Session(out Sink sink){var s=new TransferSession();sink=new Sink("box");s.Register(new TransferTargetDescriptor("box",TransferTargetKind.Box,0,0,0,0,1,1,"base",true),sink);return s;}
        private static AimSample Sample(int tick,AimSource source)=>source==AimSource.MousePointer?new AimSample(tick,source,10,10,true,4096,0,new SimulationTick(tick-1),new SimulationTick(tick)):new AimSample(tick,source,null,null,null,4096,0,new SimulationTick(tick-1),new SimulationTick(tick));
        private static TransferCandidateObservation Obs(string id,int tick,int screen,int angle,bool trigger=false,bool available=true)=>new TransferCandidateObservation(new TransferTargetDescriptor(id,TransferTargetKind.Box,0,0,0,0,1,1,"base",available),new SimulationTick(tick),0,0,0,0,1,1,trigger,true,36000,false,screen,angle);
        private sealed class Sink:ITransferTargetModifierSink { internal Sink(string id){BoundTargetId=id;}internal bool Accept=true,Available=true;internal int ClearCount,ApplyCount;public string BoundTargetId{get;}public bool IsStillAvailable()=>Available;public bool TryApply(TransferModifierRequest request){ApplyCount++;return Accept;}public void Clear(TransferClearReason reason,SimulationTick tick,int revision){ClearCount++;} }
    }
}
